  `organizer` varchar(191) DEFAULT 'Flugschule Hirondelle',
  `registrationDeadline` datetime(3) DEFAULT NULL,
  `categoryId` varchar(191) DEFAULT NULL,
  `alias` varchar(191) DEFAULT NULL,
  `bookableFor` varchar(191) DEFAULT 'public',
  `bookingType` varchar(191) DEFAULT 'limited',
  `currency` varchar(191) DEFAULT 'EUR',
  `eventType` varchar(191) DEFAULT 'paid',
  `feePerPerson` double DEFAULT 0,
  `googleMapsAddress` text DEFAULT NULL,
  `isHotEvent` tinyint(1) NOT NULL DEFAULT 0,
  `isTopEvent` tinyint(1) NOT NULL DEFAULT 0,
  `leadSpeaker` varchar(191) DEFAULT NULL,
  `locationType` varchar(191) DEFAULT 'custom',
  `maxBookablePerPerson` int(11) DEFAULT 1,
  `metaDescription` text DEFAULT NULL,
  `metaKeywords` text DEFAULT NULL,
  `minParticipants` int(11) DEFAULT 0,
  `onExceed` varchar(191) DEFAULT 'waitlist',
  `paymentProcessing` tinyint(1) NOT NULL DEFAULT 1,
  `published` tinyint(1) NOT NULL DEFAULT 1,
  `shortDescription` text DEFAULT NULL,
  `tags` varchar(191) DEFAULT NULL,
  `targetGroup` text DEFAULT NULL,
  `taxRate` varchar(191) DEFAULT NULL,
  `tieredFees` tinyint(1) NOT NULL DEFAULT 0,
  `calendarBgColor` varchar(191) DEFAULT '#3a87ac',
  `calendarTextColor` varchar(191) DEFAULT '#ffffff',
  `customBookingEmail` varchar(191) DEFAULT NULL,
  `customCertificate` varchar(191) DEFAULT NULL,
  `eventNumber` varchar(191) DEFAULT NULL,
  `titleOverride` varchar(191) DEFAULT NULL,
  `organizerId` varchar(191) DEFAULT NULL,
  `locationId` varchar(191) DEFAULT NULL,
  `eventTieredFees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`eventTieredFees`)),
  `seriesId` varchar(191) DEFAULT NULL,
  `cancelled` tinyint(1) NOT NULL DEFAULT 0,
  `bookingNumber` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Event_alias_key` (`alias`),
  KEY `Event_seriesId_idx` (`seriesId`),
